<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Features\Access\TenantLoginProvider\Domain\TenantLoginProviderRef;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityUserVO;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityLoginProviderVO;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentitySubjectVO;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityCreatedAtVO;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentityVersionVO;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Usecase\Create\UserFederatedIdentityCreateResult;
use PHPUnit\Framework\TestCase;

final class UserFederatedIdentityCreateResultUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new UserFederatedIdentityCreateResult();
        $userOneValue = new UserRef('one');
        $userOtherValue = new UserRef('other');
        $copy = $value->user($userOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new UserRef('one'), $value->getUser());
        $this->assertNotEquals(new UserRef('other'), $value->getUser());
        $this->assertEquals(new UserRef('one'), $value->getUserOrCurrent(UserFederatedIdentityUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('other'), $value->getUserOrCurrent(UserFederatedIdentityUserVO::from($userOtherValue))->value());
        $value->unsetUser();
        $this->assertEquals(new UserRef('other'), $value->getUserOrCurrent(UserFederatedIdentityUserVO::from($userOtherValue))->value());
        $this->assertNotEquals(new UserRef('one'), $value->getUserOrCurrent(UserFederatedIdentityUserVO::from($userOtherValue))->value());
        $loginProviderOneValue = new TenantLoginProviderRef('one');
        $loginProviderOtherValue = new TenantLoginProviderRef('other');
        $copy = $value->loginProvider($loginProviderOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TenantLoginProviderRef('one'), $value->getLoginProvider());
        $this->assertNotEquals(new TenantLoginProviderRef('other'), $value->getLoginProvider());
        $this->assertEquals(new TenantLoginProviderRef('one'), $value->getLoginProviderOrCurrent(UserFederatedIdentityLoginProviderVO::from($loginProviderOtherValue))->value());
        $this->assertNotEquals(new TenantLoginProviderRef('other'), $value->getLoginProviderOrCurrent(UserFederatedIdentityLoginProviderVO::from($loginProviderOtherValue))->value());
        $value->unsetLoginProvider();
        $this->assertEquals(new TenantLoginProviderRef('other'), $value->getLoginProviderOrCurrent(UserFederatedIdentityLoginProviderVO::from($loginProviderOtherValue))->value());
        $this->assertNotEquals(new TenantLoginProviderRef('one'), $value->getLoginProviderOrCurrent(UserFederatedIdentityLoginProviderVO::from($loginProviderOtherValue))->value());
        $subjectOneValue = 'one';
        $subjectOtherValue = 'other';
        $copy = $value->subject($subjectOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getSubject());
        $this->assertNotEquals('other', $value->getSubject());
        $this->assertEquals('one', $value->getSubjectOrCurrent(UserFederatedIdentitySubjectVO::from($subjectOtherValue))->value());
        $this->assertNotEquals('other', $value->getSubjectOrCurrent(UserFederatedIdentitySubjectVO::from($subjectOtherValue))->value());
        $value->unsetSubject();
        $this->assertEquals('other', $value->getSubjectOrCurrent(UserFederatedIdentitySubjectVO::from($subjectOtherValue))->value());
        $this->assertNotEquals('one', $value->getSubjectOrCurrent(UserFederatedIdentitySubjectVO::from($subjectOtherValue))->value());
        $createdAtOneValue = (new \DateTimeImmutable('1980-08-20T14:32:45.123Z'));
        $createdAtOtherValue = (new \DateTimeImmutable('1981-09-06T14:32:45.123Z'));
        $copy = $value->createdAt($createdAtOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getCreatedAt());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getCreatedAt());
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getCreatedAtOrCurrent(UserFederatedIdentityCreatedAtVO::from($createdAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getCreatedAtOrCurrent(UserFederatedIdentityCreatedAtVO::from($createdAtOtherValue))->value());
        $value->unsetCreatedAt();
        $this->assertEquals((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')), $value->getCreatedAtOrCurrent(UserFederatedIdentityCreatedAtVO::from($createdAtOtherValue))->value());
        $this->assertNotEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $value->getCreatedAtOrCurrent(UserFederatedIdentityCreatedAtVO::from($createdAtOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(UserFederatedIdentityVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(UserFederatedIdentityVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(UserFederatedIdentityVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(UserFederatedIdentityVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
